/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re,json
b=Path('reference/step-00-input/baseline-filtered-v2')
fr=(b/'fr-nfr.md').read_text(); flow=(b/'flow.md').read_text(); state=(b/'state-machine.md').read_text()
rows=[l.split('|')[1:-1] for l in fr.splitlines() if re.match(r'"'^'"\\| FR-\\d+ \\|',l)]
for label,txt in [('flow',flow),('state',state)]:print(label,'AC exact contained',sum(c[3].strip() in txt for c in rows),'/18')
for name,ranges in [('fr-nfr.md',[(113,126)]),('flow.md',[(239,241),(308,315),(498,504)]),('ui-mockup.html',[(344,347)])]:
 print('\\n',name)
 for n,l in enumerate((b/name).read_text().splitlines(),1):
  if not any(a<=n<=z for a,z in ranges):continue
  if name=='flow.md':
   c=l.split('|')[1:-1]
   if n in [239,240,241]:l=' | '.join([c[0],c[2],c[6],c[7]])
   else:l=' | '.join(c[:4])
  if name=='ui-mockup.html':
   l=' ... '.join(re.findall(r'.{0,70}(?:menu-item-|option-|US-07|ETA).{0,140}',l))
  print(n,l[:1100])
PY"

